import math

def is_power_of_three(n):
    if n <= 0:
        return False
    if n == 1: # 3^0 = 1. If we restrict to powers 3^x with x>=1, this should be False, but generally 1 is a power of 3. The problem implies positive integers, so 3^x >= 3^1 = 3.
        return False 

    # Check if it's divisible by 3 repeatedly until 1.
    while n > 1:
        if n % 3 != 0:
            return False
        n //= 3
    return True

solutions = []
limit = 50

for a in range(1, limit + 1):
    for b in range(a, limit + 1):
        val1 = a**2 + b
        val2 = b**2 + a

        # Optimization: If either value is too small to be a power of 3 (i.e., less than 3), skip.
        if val1 < 3 or val2 < 3:
            continue

        if is_power_of_three(val1) and is_power_of_three(val2):
            solutions.append((a, b))

print(f"Found solutions (a, b): {solutions}")
